catalog_sql:
SELECT json_build_object(
 'columns', (SELECT json_agg(row_to_json(c) ORDER BY c.table_name,c.ordinal_position) FROM (SELECT table_schema,table_name,column_name,ordinal_position,data_type,udt_name,is_nullable,character_maximum_length,numeric_precision,numeric_scale,datetime_precision,is_identity,is_generated FROM information_schema.columns WHERE table_schema='public') c),
 'foreign_keys',(SELECT json_agg(row_to_json(f) ORDER BY f.child_table,f.name) FROM (SELECT co.conname AS name,cl.relname AS child_table,pa.relname AS parent_table, co.condeferrable AS deferrable, co.condeferred AS deferred, array(SELECT a.attname FROM unnest(co.conkey) WITH ORDINALITY k(n,o) JOIN pg_attribute a ON a.attrelid=co.conrelid AND a.attnum=k.n ORDER BY k.o) AS child_columns, array(SELECT a.attname FROM unnest(co.confkey) WITH ORDINALITY k(n,o) JOIN pg_attribute a ON a.attrelid=co.confrelid AND a.attnum=k.n ORDER BY k.o) AS parent_columns FROM pg_constraint co JOIN pg_class cl ON cl.oid=co.conrelid JOIN pg_namespace ns ON ns.oid=cl.relnamespace JOIN pg_class pa ON pa.oid=co.confrelid WHERE co.contype='f' AND ns.nspname='public') f),
 'primary_keys',(SELECT json_agg(row_to_json(p) ORDER BY p.table_name) FROM (SELECT cl.relname AS table_name, array(SELECT a.attname FROM unnest(co.conkey) WITH ORDINALITY k(n,o) JOIN pg_attribute a ON a.attrelid=co.conrelid AND a.attnum=k.n ORDER BY k.o) AS columns FROM pg_constraint co JOIN pg_class cl ON cl.oid=co.conrelid JOIN pg_namespace ns ON ns.oid=cl.relnamespace WHERE co.contype='p' AND ns.nspname='public') p)
);
